package com.luminor.tavernquest.data.repository
import androidx.room.withTransaction;import com.luminor.tavernquest.data.local.database.TavernQuestDatabase;import com.luminor.tavernquest.data.local.database.entity.TavernMemberEntity;import com.luminor.tavernquest.data.mapper.*;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.repository.TavernRepository;import kotlinx.coroutines.flow.map
class TavernRepositoryImpl(private val db:TavernQuestDatabase):TavernRepository{override suspend fun create(tavern:Tavern,owner:TavernMember)=db.withTransaction{db.tavernDao().insert(tavern.toEntity());db.tavernMemberDao().insert(TavernMemberEntity(owner.id,owner.tavernId,owner.heroId,owner.role.name,owner.joinedAt))};override suspend fun get()=db.tavernDao().getTavern()?.toDomain();override fun observe()=db.tavernDao().observeTavern().map{it?.toDomain()}}
